import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def load_json_file(file_path):
    """Load and parse a JSON file."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, FileNotFoundError):
        return None

def extract_fact_value(award, fact_name):
    """Extract the value for a specific fact from an award object."""
    if fact_name == "performance start":
        # period_of_performance.start_date
        pop = award.get("period_of_performance", {})
        value = pop.get("start_date")
        if value:
            # Ensure date format is YYYY-MM-DD (strip time if present)
            if " " in value:
                value = value.split(" ")[0]
        return value
    elif fact_name == "performance end":
        # period_of_performance.end_date
        pop = award.get("period_of_performance", {})
        value = pop.get("end_date")
        if value:
            if " " in value:
                value = value.split(" ")[0]
        return value
    elif fact_name == "amount obligated":
        # total_obligation
        value = award.get("total_obligation")
        # Convert to string if numeric, handle None
        if value is None:
            return None
        # Ensure it's a decimal string
        return str(value)
    elif fact_name == "potential value":
        # base_and_all_options
        value = award.get("base_and_all_options")
        if value is None:
            return None
        return str(value)
    return None

def process_packet(packet_dir, manifest):
    """Main processing function."""
    # Load the usaspending_awards.json file
    awards_file = Path(packet_dir) / "usaspending_awards.json"
    awards_data = load_json_file(awards_file)
    if awards_data is None:
        # If file not found or invalid, return empty results
        return {pair: {} for pair in manifest["pairs"]}

    # Build a mapping from generated_unique_award_id to award object
    awards_by_id = {}
    for award in awards_data:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            awards_by_id[award_id] = award

    # Process each pair in the manifest
    results = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        award = awards_by_id.get(entity)

        if award is None:
            # Award not found, all facts are ABSENT
            fact_results = {}
            for fact_name in manifest["facts"][rule_id]:
                fact_results[fact_name] = "ABSENT"
            results[pair] = fact_results
            continue

        # Process each fact for this rule
        fact_results = {}
        for fact_name in manifest["facts"][rule_id]:
            value = extract_fact_value(award, fact_name)
            if value is None:
                fact_results[fact_name] = "ABSENT"
            else:
                # For dates, ensure YYYY-MM-DD format
                if fact_name in ["performance start", "performance end"]:
                    # Already processed in extract_fact_value
                    pass
                # For amounts, ensure decimal string
                elif fact_name in ["amount obligated", "potential value"]:
                    # Convert to string with proper decimal representation
                    try:
                        # Remove trailing .0 if integer
                        if "." in value:
                            value = value.rstrip('0').rstrip('.')
                    except:
                        pass
                fact_results[fact_name] = [value, "usaspending_awards"]

        results[pair] = fact_results

    return results

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    manifest = load_json_file(manifest_path)
    if manifest is None:
        print("{}")
        sys.exit(1)

    # Process the packet
    results = process_packet(packet_dir, manifest)

    # Output as JSON
    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()
