def load_json_file(file_path):
    """Load JSON data from a file."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, FileNotFoundError):
        return None

def parse_date(date_str):
    """Parse a date string in YYYY-MM-DD format."""
    if not date_str:
        return None
    try:
        return datetime.strptime(date_str, "%Y-%m-%d").date()
    except (ValueError, TypeError):
        return None

def extract_facts_from_award(award, rule_id, facts_needed):
    """Extract required facts from a single award based on rule."""
    result = {}

    if rule_id == "usa.period_3y":
        for fact in facts_needed:
            if fact == "performance start":
                start_date = award.get("period_of_performance", {}).get("start_date")
                if start_date:
                    result[fact] = [start_date, "usaspending_awards"]
                else:
                    result[fact] = "ABSENT"
            elif fact == "performance end":
                end_date = award.get("period_of_performance", {}).get("end_date")
                if end_date:
                    result[fact] = [end_date, "usaspending_awards"]
                else:
                    result[fact] = "ABSENT"

    elif rule_id == "usa.obligated_95":
        for fact in facts_needed:
            if fact == "amount obligated":
                obligated = award.get("total_obligation")
                if obligated is not None:
                    # Format as decimal string
                    result[fact] = [f"{obligated:.2f}", "usaspending_awards"]
                else:
                    result[fact] = "ABSENT"
            elif fact == "potential value":
                potential = award.get("base_and_all_options")
                if potential is not None:
                    result[fact] = [f"{potential:.2f}", "usaspending_awards"]
                else:
                    result[fact] = "ABSENT"

    return result

def main(packet_dir, manifest_path):
    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load usaspending_awards data
    awards_file = Path(packet_dir) / "usaspending_awards.json"
    awards_data = load_json_file(awards_file)
    if awards_data is None:
        # If file doesn't exist or is invalid, return empty results
        print(json.dumps({}))
        return

    # Create mapping from generated_unique_award_id to award
    awards_by_id = {}
    for award in awards_data:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            awards_by_id[award_id] = award

    # Process each pair
    results = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)

        if entity not in awards_by_id:
            # Award not found, all facts are ABSENT
            results[pair] = {fact: "ABSENT" for fact in manifest["facts"][rule_id]}
            continue

        award = awards_by_id[entity]
        facts_needed = manifest["facts"][rule_id]

        # Extract facts for this award
        facts = extract_facts_from_award(award, rule_id, facts_needed)

        # Check for conflicts (multiple awards with same ID shouldn't happen here,
        # but we handle it if the data structure changes)
        results[pair] = facts

    # Output results as JSON
    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    main(sys.argv[1], sys.argv[2])
