import json
import os
import sys
from datetime import datetime, timedelta
from typing import Any, Dict, List, Optional, Tuple, Union

def load_json_file(filepath: str) -> Any:
    """Load JSON data from a file."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_date(date_str: Optional[str]) -> Optional[datetime]:
    """Parse a date string in YYYY-MM-DD format."""
    if not date_str:
        return None
    try:
        return datetime.strptime(date_str, '%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def extract_fact_value(award: Dict[str, Any], fact_name: str, rule_id: str) -> Tuple[Optional[Union[str, float]], str]:
    """
    Extract the value for a given fact from an award record.
    Returns (value, document_name) where document_name is the filename without extension.
    """
    # Map fact names to their JSON paths based on the decision rules
    fact_paths = {
        "performance start": ("period_of_performance", "start_date"),
        "performance end": ("period_of_performance", "end_date"),
        "amount obligated": ("total_obligation",),
        "potential value": ("base_and_all_options",),
    }

    if fact_name not in fact_paths:
        return None, ""

    path = fact_paths[fact_name]
    value = award
    try:
        for key in path:
            value = value[key]
    except (KeyError, TypeError):
        return None, ""

    # Determine the document name based on rule_id
    if rule_id == "usa.period_3y" or rule_id == "usa.obligated_95":
        document_name = "usaspending_awards"
    else:
        # This shouldn't happen with the given rules, but handle generically
        document_name = "usaspending_awards"

    return value, document_name

def process_pair(packet_dir: str, pair: str, facts: List[str], rule_id: str, all_awards: List[Dict[str, Any]]) -> Dict[str, Any]:
    """
    Process a single pair (rule_id::entity) and return the facts for that entity.
    """
    entity_id = pair.split("::")[1]

    # Find all awards matching this entity_id
    matching_awards = []
    for award in all_awards:
        if award.get("generated_unique_award_id") == entity_id:
            matching_awards.append(award)

    result = {}

    for fact_name in facts:
        values = []
        documents = []

        for award in matching_awards:
            value, doc_name = extract_fact_value(award, fact_name, rule_id)
            if value is not None:
                values.append(value)
                documents.append(doc_name)

        if not values:
            result[fact_name] = "ABSENT"
        elif len(set(values)) > 1:
            result[fact_name] = "CONFLICT"
        else:
            # All values agree, use the first one
            # Format dates as YYYY-MM-DD
            if fact_name in ["performance start", "performance end"]:
                date_val = parse_date(values[0])
                if date_val:
                    formatted_value = date_val.strftime('%Y-%m-%d')
                else:
                    formatted_value = str(values[0])
            else:
                # For amounts, convert to string (decimal)
                if isinstance(values[0], (int, float)):
                    formatted_value = str(values[0])
                else:
                    formatted_value = str(values[0])

            result[fact_name] = [formatted_value, documents[0]]

    return result

def main(packet_dir: str, manifest_path: str):
    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load the awards data
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    all_awards = load_json_file(awards_file)

    # Process each pair
    output = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::")
        facts_needed = manifest["facts"][rule_id]

        result = process_pair(packet_dir, pair, facts_needed, rule_id, all_awards)
        output[pair] = result

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]
    main(packet_dir, manifest_path)
