import json
import os
import sys
from datetime import datetime, timedelta
from typing import Dict, Any, List, Optional, Tuple, Union

def load_json_file(filepath: str) -> Any:
    """Load JSON data from a file."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_date(date_str: Optional[str]) -> Optional[datetime]:
    """Parse a date string to datetime object, handling None and empty strings."""
    if not date_str:
        return None
    try:
        # Handle dates with time components
        if ' ' in date_str:
            return datetime.strptime(date_str.split()[0], '%Y-%m-%d')
        return datetime.strptime(date_str, '%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def extract_fact_value(award: Dict[str, Any], fact_name: str, rule_id: str) -> Tuple[Optional[Any], str]:
    """
    Extract the value for a specific fact from an award record.
    Returns (value, document_name) or (None, document_name) if ABSENT.
    """
    # Map fact names to their field paths based on decision rules
    field_map = {
        'performance start': ('period_of_performance', 'start_date'),
        'performance end': ('period_of_performance', 'end_date'),
        'amount obligated': ('total_obligation',),
        'potential value': ('base_and_all_options',),
    }

    if fact_name not in field_map:
        return None, ''

    # Navigate through the award dictionary
    path = field_map[fact_name]
    value = award
    try:
        for key in path:
            value = value[key]
    except (KeyError, TypeError):
        return None, 'usaspending_awards'  # ABSENT

    # For dates, ensure they're in YYYY-MM-DD format
    if fact_name in ['performance start', 'performance end'] and value:
        date_obj = parse_date(value)
        if date_obj:
            value = date_obj.strftime('%Y-%m-%d')

    # For amounts, convert to string with proper decimal representation
    if fact_name in ['amount obligated', 'potential value'] and value is not None:
        if isinstance(value, (int, float)):
            # Remove trailing .0 if integer
            if value == int(value):
                value = str(int(value))
            else:
                value = str(value)
        else:
            value = str(value)

    return value, 'usaspending_awards'

def process_pair(packet_dir: str, pair: str, facts: List[str], all_awards: List[Dict[str, Any]]) -> Dict[str, Union[str, List]]:
    """
    Process a single rule_id::entity pair.
    Returns a dictionary mapping fact names to their values.
    """
    rule_id, entity = pair.split('::', 1)
    result = {}

    # Find all awards for this entity (generated_unique_award_id)
    entity_awards = [award for award in all_awards if award.get('generated_unique_award_id') == entity]

    for fact_name in facts:
        values = []
        documents = []

        for award in entity_awards:
            value, doc = extract_fact_value(award, fact_name, rule_id)
            if value is not None:
                values.append(value)
                documents.append(doc)

        if not values:
            result[fact_name] = "ABSENT"
        elif len(set(values)) == 1:
            # All values agree
            result[fact_name] = [values[0], documents[0]]
        else:
            # Conflicting values
            result[fact_name] = "CONFLICT"

    return result

def main(packet_dir: str, manifest_path: str):
    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load awards data
    awards_file = os.path.join(packet_dir, 'usaspending_awards.json')
    all_awards = load_json_file(awards_file)

    # Process each pair
    output = {}
    for pair in manifest['pairs']:
        rule_id = pair.split('::')[0]
        facts = manifest['facts'][rule_id]
        output[pair] = process_pair(packet_dir, pair, facts, all_awards)

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    main(packet_dir, manifest_path)
