import json
import os
import sys
from datetime import datetime, timedelta
from typing import Dict, List, Any, Optional, Union

def load_json_file(filepath: str) -> Any:
    """Load JSON data from a file."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_date(date_str: Optional[str]) -> Optional[datetime]:
    """Parse a date string in YYYY-MM-DD format."""
    if not date_str:
        return None
    try:
        # Handle potential time component
        if ' ' in date_str:
            date_part = date_str.split(' ')[0]
            return datetime.strptime(date_part, '%Y-%m-%d')
        return datetime.strptime(date_str, '%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def extract_fact_value(award: Dict[str, Any], fact_name: str) -> Optional[Union[str, float]]:
    """Extract a fact value from an award based on the fact name."""
    if fact_name == "performance start":
        start_date = award.get("period_of_performance", {}).get("start_date")
        if start_date:
            parsed = parse_date(start_date)
            return parsed.strftime("%Y-%m-%d") if parsed else None
        return None
    elif fact_name == "performance end":
        end_date = award.get("period_of_performance", {}).get("end_date")
        if end_date:
            parsed = parse_date(end_date)
            return parsed.strftime("%Y-%m-%d") if parsed else None
        return None
    elif fact_name == "amount obligated":
        value = award.get("total_obligation")
        if value is None:
            return None
        try:
            # Ensure it's a number
            return float(value)
        except (ValueError, TypeError):
            return None
    elif fact_name == "potential value":
        value = award.get("base_and_all_options")
        if value is None:
            return None
        try:
            return float(value)
        except (ValueError, TypeError):
            return None
    return None

def process_packet(packet_dir: str, manifest_path: str) -> Dict[str, Any]:
    """Main processing function."""
    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load awards data
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards_data = load_json_file(awards_file)

    # Create a mapping from generated_unique_award_id to award
    awards_by_id = {award["generated_unique_award_id"]: award for award in awards_data}

    # Initialize result structure
    result = {}

    # Process each pair
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)

        if entity not in awards_by_id:
            # Entity not found in awards
            fact_names = manifest["facts"][rule_id]
            result[pair] = {fact: "ABSENT" for fact in fact_names}
            continue

        award = awards_by_id[entity]
        fact_names = manifest["facts"][rule_id]

        # For each fact, extract value
        fact_values = {}
        for fact_name in fact_names:
            value = extract_fact_value(award, fact_name)
            if value is None:
                fact_values[fact_name] = "ABSENT"
            else:
                # Format numeric values as decimal strings
                if isinstance(value, float):
                    # Remove trailing .0 if integer
                    if value.is_integer():
                        value_str = str(int(value))
                    else:
                        value_str = str(value)
                else:
                    value_str = str(value)
                fact_values[fact_name] = [value_str, "usaspending_awards"]

        result[pair] = fact_values

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    result = process_packet(packet_dir, manifest_path)
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
